target.css:
:root {
  --paper: #fffdf5;
  --ink: #253544;
  --coral: #db6654;
  --sage: #dce8da;
  --line: #c8d3cc;
  --muted: #697878;
}

article.postcard {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 16px;
  border-bottom: 1px solid var(--line);
}

.route-mark {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.3px;
  color: var(--muted);
}

.table-badge {
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--sage);
  font-size: 11px;
  font-weight: 700;
  color: var(--ink);
}

.address-panel {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
}

.stamp-mark {
  display: grid;
  width: 54px;
  height: 54px;
  flex: 0 0 auto;
  place-items: center;
  border: 2px dashed var(--coral);
  border-radius: 8px;
  color: var(--coral);
  font-size: 27px;
}

.recipient {
  min-width: 0;
}

.greeting {
  margin: 0 0 3px;
  font-size: 12px;
  color: var(--muted);
}

.card-title {
  margin: 0;
  font-size: 21px;
  line-height: 1.16;
  letter-spacing: -0.4px;
}

.exchange-details {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.detail {
  padding: 10px 16px 11px;
}

.detail + .detail {
  border-left: 1px solid var(--line);
}

.detail dt {
  margin-bottom: 3px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--coral);
}

.detail dd {
  margin: 0;
  font-size: 12px;
  font-weight: 600;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 16px;
}

.note {
  margin: 0;
  font-size: 12px;
  color: var(--muted);
}

.check-button {
  border: 0;
  border-radius: 7px;
  padding: 7px 10px;
  background: var(--coral);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}
